const response = $input.first()?.json;
if (!response?.ok) {
  throw new Error(`Telegram getUpdates fehlgeschlagen: ${JSON.stringify(response)}`);
}

const updates = response.result ?? [];
if (updates.length === 0) return [];

const allowedUserIds = new Set(['REPLACE_WITH_YOUR_TELEGRAM_USER_ID']);
if (allowedUserIds.has('REPLACE_WITH_YOUR_TELEGRAM_USER_ID')) {
  throw new Error('Bitte in diesem Code-Node REPLACE_WITH_YOUR_TELEGRAM_USER_ID durch deine numerische Telegram-ID ersetzen.');
}

const state = $getWorkflowStaticData('global');
state.telegramUpdateOffset = Math.max(...updates.map(update => update.update_id)) + 1;

return updates.flatMap(update => {
  const message = update.message;
  const callback = update.callback_query;
  const from = message?.from ?? callback?.from;
  const chatId = message?.chat?.id ?? callback?.message?.chat?.id;
  if (!from || !chatId || from.is_bot || !allowedUserIds.has(String(from.id))) return [];

  return [{
    json: {
      telegramUserId: String(from.id),
      chatId: String(chatId),
      updateId: String(update.update_id),
      text: message?.text ?? null,
      callbackData: callback?.data ?? null,
      callbackQueryId: callback?.id ?? null
    }
  }];
});

const rooms = ['Wohnzimmer', 'Schlafzimmer', 'Flur', 'Bad', 'Küche', 'GaesteBad', 'Abstellkammer', 'Witchy'];
const current = $json;
let draft = current.draft ?? {};
if (typeof draft === 'string') draft = JSON.parse(draft);
let state = current.state ?? null;
let removeConversation = false;
let saveEntry = false;
let reply = '';
let keyboard = undefined;
const text = String(current.message_text ?? '').trim();
const callback = String(current.callback_data ?? '');
const command = text.split(/\s+/)[0].toLowerCase();
const berlinTime = value => new Intl.DateTimeFormat('de-DE', { timeZone: 'Europe/Berlin', dateStyle: 'short', timeStyle: 'short' }).format(new Date(value));
const buttons = rows => ({ inline_keyboard: rows });
const roomKeyboard = buttons([
  [{ text: rooms[0], callback_data: `room:${rooms[0]}` }, { text: rooms[1], callback_data: `room:${rooms[1]}` }],
  [{ text: rooms[2], callback_data: `room:${rooms[2]}` }, { text: rooms[3], callback_data: `room:${rooms[3]}` }],
  [{ text: rooms[4], callback_data: `room:${rooms[4]}` }, { text: rooms[5], callback_data: `room:${rooms[5]}` }],
  [{ text: rooms[6], callback_data: `room:${rooms[6]}` }, { text: rooms[7], callback_data: `room:${rooms[7]}` }]
]);
const methodKeyboard = buttons([
  [{ text: 'Stoßlüften', callback_data: 'method:shock' }, { text: 'Querlüften', callback_data: 'method:cross' }],
  [{ text: 'Kippfenster', callback_data: 'method:tilted_window' }, { text: 'Sonstiges', callback_data: 'method:other' }],
  [{ text: 'Überspringen', callback_data: 'skip' }]
]);
const skipKeyboard = buttons([[{ text: 'Überspringen', callback_data: 'skip' }]]);
const cancelKeyboard = buttons([[{ text: 'Abbrechen', callback_data: 'cancel' }]]);
const confirmationKeyboard = buttons([[{ text: 'Speichern', callback_data: 'save' }, { text: 'Abbrechen', callback_data: 'cancel' }]]);

if (command === '/start' || command === '/neu') {
  state = 'ventilated_at';
  draft = {};
  reply = 'Neuer Lüftungseintrag. Wann wurde gelüftet? Antworte mit „jetzt“ oder Datum und Uhrzeit im Format TT.MM.JJJJ HH:MM (deutsche Ortszeit).';
  keyboard = buttons([[{ text: 'Jetzt', callback_data: 'time:now' }, { text: 'Abbrechen', callback_data: 'cancel' }]]);
} else if (command === '/abbrechen' || callback === 'cancel') {
  state = null;
  draft = {};
  removeConversation = true;
  reply = 'Eingabe abgebrochen. Für einen neuen Eintrag sende /neu.';
} else if (state === 'ventilated_at') {
  if (callback === 'time:now' || /^jetzt$/i.test(text)) {
    draft.ventilated_at = new Date().toISOString();
    state = 'room';
    reply = 'Welcher Raum?';
    keyboard = roomKeyboard;
  } else {
    const match = text.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})\s+(\d{1,2}):(\d{2})$/);
    if (!match) {
      reply = 'Bitte „jetzt“ wählen oder Datum und Uhrzeit als TT.MM.JJJJ HH:MM eingeben.';
      keyboard = buttons([[{ text: 'Jetzt', callback_data: 'time:now' }, { text: 'Abbrechen', callback_data: 'cancel' }]]);
    } else {
      const [, d, m, y, h, min] = match;
      const wanted = { day: Number(d), month: Number(m), year: Number(y), hour: Number(h), minute: Number(min) };
      const target = Date.UTC(wanted.year, wanted.month - 1, wanted.day, wanted.hour, wanted.minute);
      const utcCheck = new Date(target);
      if (utcCheck.getUTCFullYear() !== wanted.year || utcCheck.getUTCMonth() !== wanted.month - 1 || utcCheck.getUTCDate() !== wanted.day || wanted.hour > 23 || wanted.minute > 59) {
        reply = 'Das Datum oder die Uhrzeit ist ungültig. Bitte erneut als TT.MM.JJJJ HH:MM eingeben.';
      } else {
        const formatter = new Intl.DateTimeFormat('en-GB', { timeZone: 'Europe/Berlin', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' });
        const candidates = [];
        for (const offsetMinutes of [-120, -60, 0, 60, 120, 180]) {
          const candidate = target - offsetMinutes * 60000;
          const parts = Object.fromEntries(formatter.formatToParts(new Date(candidate)).map(part => [part.type, part.value]));
          if (Number(parts.year) === wanted.year && Number(parts.month) === wanted.month && Number(parts.day) === wanted.day && Number(parts.hour) === wanted.hour && Number(parts.minute) === wanted.minute) candidates.push(candidate);
        }
        if (candidates.length === 0) {
          reply = 'Diese Ortszeit gibt es wegen der Zeitumstellung nicht. Bitte eine andere Uhrzeit eingeben.';
        } else {
          draft.ventilated_at = new Date(Math.min(...candidates)).toISOString();
          state = 'room';
          reply = 'Welcher Raum?';
          keyboard = roomKeyboard;
        }
      }
    }
  }
} else if (state === 'room') {
  const room = callback.startsWith('room:') ? callback.slice(5) : text;
  if (!rooms.includes(room)) {
    reply = 'Bitte wähle einen Raum über die Buttons.';
    keyboard = roomKeyboard;
  } else {
    draft.room = room;
    state = 'duration';
    reply = `Wie viele Minuten wurde in ${room} gelüftet? Bitte eine ganze Zahl von 1 bis 480 eingeben.`;
    keyboard = cancelKeyboard;
  }
} else if (state === 'duration') {
  const duration = Number(text);
  if (!Number.isInteger(duration) || duration < 1 || duration > 480) {
    reply = 'Bitte eine ganze Dauer zwischen 1 und 480 Minuten eingeben.';
    keyboard = cancelKeyboard;
  } else {
    draft.duration_minutes = duration;
    state = 'ventilation_method';
    reply = 'Wie wurde gelüftet?';
    keyboard = methodKeyboard;
  }
} else if (state === 'ventilation_method') {
  const method = callback.startsWith('method:') ? callback.slice(7) : '';
  if (method && !['shock', 'cross', 'tilted_window', 'other'].includes(method) && callback !== 'skip') {
    reply = 'Bitte wähle eine Lüftungsart oder überspringe diesen Schritt.';
    keyboard = methodKeyboard;
  } else {
    draft.ventilation_method = method || null;
    state = 'temperature';
    reply = 'Raumtemperatur in °C? Zahl eingeben oder überspringen.';
    keyboard = skipKeyboard;
  }
} else if (state === 'temperature') {
  if (callback === 'skip' || /^überspringen$/i.test(text)) {
    draft.temperature_c = null;
  } else {
    const value = Number(text.replace(',', '.').replace(/\s*°\s*c?$/i, ''));
    if (!Number.isFinite(value) || value < -30 || value > 80) {
      reply = 'Bitte eine Temperatur zwischen -30 und 80 °C eingeben oder überspringen.';
      keyboard = skipKeyboard;
    } else {
      draft.temperature_c = value;
    }
  }
  if (reply === '') {
    state = 'humidity';
    reply = 'Relative Luftfeuchtigkeit in Prozent? Zahl eingeben oder überspringen.';
    keyboard = skipKeyboard;
  }
} else if (state === 'humidity') {
  if (callback === 'skip' || /^überspringen$/i.test(text)) {
    draft.relative_humidity_percent = null;
  } else {
    const value = Number(text.replace(',', '.').replace(/\s*%$/, ''));
    if (!Number.isFinite(value) || value < 0 || value > 100) {
      reply = 'Bitte eine Luftfeuchtigkeit zwischen 0 und 100 % eingeben oder überspringen.';
      keyboard = skipKeyboard;
    } else {
      draft.relative_humidity_percent = value;
    }
  }
  if (reply === '') {
    state = 'confirm';
    const methodNames = { shock: 'Stoßlüften', cross: 'Querlüften', tilted_window: 'Kippfenster', other: 'Sonstiges' };
    reply = `Bitte prüfen:\nRaum: ${draft.room}\nZeit: ${berlinTime(draft.ventilated_at)}\nDauer: ${draft.duration_minutes} Minuten\nLüftungsart: ${methodNames[draft.ventilation_method] ?? 'nicht angegeben'}\nTemperatur: ${draft.temperature_c == null ? 'nicht angegeben' : `${draft.temperature_c} °C`}\nLuftfeuchtigkeit: ${draft.relative_humidity_percent == null ? 'nicht angegeben' : `${draft.relative_humidity_percent} %`}\n\nEintrag speichern?`;
    keyboard = confirmationKeyboard;
  }
} else if (state === 'confirm') {
  if (callback === 'save') {
    saveEntry = true;
    removeConversation = true;
    state = null;
    reply = 'Eintrag wurde gespeichert. Für einen weiteren sende /neu.';
  } else {
    reply = 'Bitte bestätige mit „Speichern“ oder brich ab.';
    keyboard = confirmationKeyboard;
  }
} else {
  state = null;
  draft = {};
  reply = 'Hallo! Sende /neu, um einen Lüftungseintrag anzulegen.';
}

return [{ json: {
  telegramUserId: current.telegram_user_id,
  chatId: current.chat_id,
  callbackQueryId: current.callback_query_id,
  state,
  draft,
  removeConversation,
  saveEntry,
  reply,
  replyMarkup: keyboard ?? null
} }];
